    /**
     * Tie/continuity-corrected Mann-Whitney U test using a normal approximation.
     *
     * <p>Pools ranks, giving average ranks to ties, and reports U for the first sample. Its identical-
     * distribution null requires independent exchangeable samples. A common-shape shift model
     * supports a location interpretation; equal medians alone is insufficient. U/(n_x*n_y) estimates
     * P(X&gt;Y)+P(X=Y)/2, not a mean difference. Approximation is used at every size. O(N log N)
     * work/O(N) storage, inputs unchanged, no shared state.
     *
     * <p><b>Example</b>
     *
     * <pre>{@code
     * const auto w=dm::stats::wilcoxon_rank_sum_test({1,2,3},{4,5,6});
     * std::print("{:.0f}\n",w.statistic); // 0
     * }</pre>
     *
     * <p><b>References</b>
     *
     * <ul>
     * <li>https://stat.ethz.ch/R-manual/R-devel/library/stats/html/wilcox.test.html</li>
     * </ul>
     *
     * <p>Uses the C++ default for {@code alternative = Alternative.TwoSided}.
     *
     * <p>C++: {@code HypothesisTestResult datamunge::stats::wilcoxon_rank_sum_test(const std::vector<double> & x, const std::vector<double> & y, Alternative alternative = TwoSided)}
     *
     * @param x Nonempty finite first sample.
     * @param y Nonempty finite independent second sample.
     * @return statistic=U=rank_sum(x)-n_x(n_x+1)/2 and approximate p_value; no CI or location estimate.
     * @throws NativeError.InvalidArgument Empty/nonfinite samples, invalid alternative or zero rank variance (all pooled observations tied). (C++ {@code std::invalid_argument})
     * @see HypothesisTestResult
     */
    public static HypothesisTestResult wilcoxonRankSumTest(double[] x, double[] y) {
        return Rosetta.asObject(Rosetta.call(206, x, y), HypothesisTestResult.class);
    }

