    /**
     * Inserts knots into a clamped B-spline basis (Oslo algorithm).
     *
     * <p>Builds the refined knot vector (old knots merged with {@code inserted_knots}) and the sparse
     * discrete-B-spline operator that re-expresses every coarse spline on it exactly. Each
     * row has at most degree + 1 nonzeros and the work is O(m p^2) for m refined functions.
     *
     * <p><b>Example</b>
     *
     * <pre>{@code
     * auto coarse = dm::fda::BSplineBasis::open_uniform(1, 2);   // knots 0 0 1 1
     * auto r = dm::fda::refine_basis(coarse, {0.25});
     * std::print("{}\n", r.apply({0.0, 4.0}));                   // [0, 1, 4]
     * }</pre>
     *
     * <p><b>References</b>
     *
     * <ul>
     * <li>E. Cohen, T. Lyche and R. Riesenfeld (1980). Discrete B-splines and subdivision
     * techniques in computer-aided geometric design and computer graphics. Computer Graphics
     * and Image Processing 14(2), 87-111. https://doi.org/10.1016/0146-664X(80)90040-4</li>
     * <li>W. Boehm (1980). Inserting new knots into B-spline curves. Computer-Aided Design
     * 12(4), 199-201. https://doi.org/10.1016/0010-4485(80)90154-2</li>
     * </ul>
     *
     * <p>C++: {@code BSplineRefinement datamunge::fda::refine_basis(const BSplineBasis & basis, const std::vector<double> & inserted_knots)}
     *
     * @param basis Basis to refine; its knot vector must be clamped (first and last knots repeated degree + 1 times, as produced by BSplineBasis::open_uniform()).
     * @param insertedKnots Knots to add, strictly inside the domain, in any order. Repeats are allowed while every knot multiplicity stays &lt;= degree + 1.
     * @return The refined basis and its refinement operator.
     * @throws NativeError.InvalidArgument If the basis is not clamped, a knot is outside the open domain or non-finite, or a multiplicity would exceed degree + 1. (C++ {@code std::invalid_argument})
     * @see Datamunge#dyadicRefine
     */
    public static BSplineRefinement refineBasis(BSplineBasis basis, double[] insertedKnots) {
        return Rosetta.asObject(Rosetta.call(234, basis, insertedKnots), BSplineRefinement.class);
    }

